00,"hd":"6d6","thac0":17,"aacBonus":2,"saves":{"death":10,"wands":11,"paralysis":11,"breath":13,"spells":12},"spells":[2,2,2]},{"level":7,"xp":120000,"hd":"7d6","thac0":14,"aacBonus":5,"saves":{"death":8,"wands":9,"paralysis":9,"breath":10,"spells":10},"spells":[3,2,2,1]},{"level":8,"xp":250000,"hd":"8d6","thac0":14,"aacBonus":5,"saves":{"death":8,"wands":9,"paralysis":9,"breath":10,"spells":10},"spells":[3,3,2,2]},{"level":9,"xp":400000,"hd":"9d6","thac0":14,"aacBonus":5,"saves":{"death":8,"wands":9,"paralysis":9,"breath":10,"spells":10},"spells":[3,3,3,2,1]},{"level":10,"xp":600000,"hd":"9d6+2","thac0":12,"aacBonus":7,"saves":{"death":6,"wands":7,"paralysis":8,"breath":8,"spells":8},"spells":[3,3,3,3,2]}],"ruleset":"classic"}'::jsonb,'ose'),
