('ose.spell.clerigo_curar_ferimentos_leves_classic','Curar Ferimentos Leves',1,FALSE,FALSE,'classic','Old-School Essentials — Tomo do Jogador',128,'{"id":"clerigo_curar_ferimentos_leves","name":"Curar Ferimentos Leves","nameEn":"Cure Light Wounds","className":"clerigo","circle":1,"range":"Toque","duration":"Instantânea","reversible":true,"reversibleName":"Causar Ferimentos Leves","description":"Cura 1d6+1 pontos de vida de uma criatura viva tocada. A versão reversa inflige 1d6+1 pontos de dano em um ataque de toque bem-sucedido.","system_id":"ose","ruleset":"classic"}'::jsonb,'ose'),
('ose.spell.clerigo_detectar_mal_classic','Detectar o Mal',1,FALSE,FALSE,'classic','Old-School Essentials — Tomo do Jogador',128,'{"id":"clerigo_detectar_mal","name":"Detectar o Mal","nameEn":"Detect Evil","className":"clerigo","circle":1,"range":"36m","duration":"6 turnos (1 hora)","reversible":false,"description":"Objetos encantados malignos ou criaturas com intenções hostis brilham com uma aura avermelhada.","system_id":"ose","ruleset":"classic"}'::jsonb,'ose'),
('ose.spell.clerigo_detectar_magia_classic','Detectar Magia',1,FALSE,FALSE,'classic','Old-School Essentials — Tomo do Jogador',128,'{"id":"clerigo_detectar_magia","name":"Detectar Magia","nameEn":"Detect Magic","className":"clerigo","circle":1,"range":"9m","duration":"2 turnos (20 min)","reversible":false,"description":"Itens, áreas ou criaturas mágicas emitem um brilho suave e visível aos olhos do conjurador.","system_id":"ose","ruleset":"classic"}'::jsonb,'ose'),
