('ose.spell.clerigo_protecao_contra_o_mal_classic','Proteção contra o Mal',1,FALSE,FALSE,'classic','Old-School Essentials — Tomo do Jogador',128,'{"id":"clerigo_protecao_contra_o_mal","name":"Proteção contra o Mal","nameEn":"Protection from Evil","className":"clerigo","circle":1,"range":"O conjurador","duration":"12 turnos","reversible":false,"description":"Uma barreira sagrada concede +1 em testes de proteção e -1 na CA contra ataques de monstros malignos e impede ataques naturais de criaturas invocadas.","system_id":"ose","ruleset":"classic"}'::jsonb,'ose'),
